def impersonate(request, user_id):
    if not request.user.is_staff:
        return HttpResponseForbidden()
    target = User.objects.get(pk=user_id)
    login(request, target)
    audit.write(f"staff {request.user.id} acting as {target.id}")
    return redirect("/")

